values
('bmlt-bacteriology-ast1-practice-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Which culture medium is commonly used for isolation of Salmonella and Shigella from stool?","translation":"","options":["XLD agar","Sabouraud agar","Lowenstein–Jensen medium","CLED agar"],"correctIndex":0,"explanation":"XLD is a selective and differential enteric pathogen medium. नेपाली: XLD agar Salmonella/Shigella छुट्याउन प्रयोग हुन्छ।","explanationNe":"XLD agar Salmonella/Shigella छुट्याउन प्रयोग हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Which organism is classically associated with swarming growth on blood agar?","translation":"","options":["Klebsiella pneumoniae","Proteus mirabilis","Shigella sonnei","Salmonella Typhi"],"correctIndex":1,"explanation":"Proteus species characteristically swarm on non-selective agar. नेपाली: Proteus मा swarming growth देखिन्छ।","explanationNe":"Proteus मा swarming growth देखिन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"A metallic sheen on EMB agar is classically produced by?","translation":"","options":["Escherichia coli","Staphylococcus aureus","Streptococcus pyogenes","Pseudomonas aeruginosa"],"correctIndex":0,"explanation":"Strong lactose fermentation by E. coli can produce a metallic green sheen. नेपाली: E. coli ले EMB मा metallic sheen दिन सक्छ।","explanationNe":"E. coli ले EMB मा metallic sheen दिन सक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Which test differentiates Staphylococcus aureus from most other staphylococci?","translation":"","options":["Coagulase test","Oxidase test","Indole test","Urease test"],"correctIndex":0,"explanation":"S. aureus is typically coagulase-positive. नेपाली: S. aureus सामान्यतया coagulase positive हुन्छ।","explanationNe":"S. aureus सामान्यतया coagulase positive हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Which organism is typically catalase-negative?","translation":"","options":["Staphylococcus aureus","Streptococcus pyogenes","Micrococcus species","Bacillus species"],"correctIndex":1,"explanation":"Streptococci are catalase-negative, unlike staphylococci. नेपाली: Streptococcus catalase negative हुन्छ।","explanationNe":"Streptococcus catalase negative हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Which test is commonly used to identify group A beta-hemolytic streptococci?","translation":"","options":["Bacitracin susceptibility/PYR test","Coagulase test","Oxidase test","Citrate test"],"correctIndex":0,"explanation":"Group A Streptococcus is typically PYR-positive and often bacitracin-susceptible; confirmation uses appropriate methods. नेपाली: PYR test GAS पहिचानमा उपयोगी हुन्छ।","explanationNe":"PYR test GAS पहिचानमा उपयोगी हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Which organism is oxidase-positive and may produce blue-green pigment?","translation":"","options":["Pseudomonas aeruginosa","Escherichia coli","Klebsiella pneumoniae","Shigella dysenteriae"],"correctIndex":0,"explanation":"P. aeruginosa is oxidase-positive and may produce pyocyanin pigment. नेपाली: Pseudomonas oxidase positive र नीलो-हरियो pigment बनाउन सक्छ।","explanationNe":"Pseudomonas oxidase positive र नीलो-हरियो pigment बनाउन सक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Which medium is preferred for routine urine culture because it helps prevent Proteus swarming?","translation":"","options":["CLED agar","Chocolate agar","TCBS agar","Mannitol salt agar"],"correctIndex":0,"explanation":"CLED supports urinary pathogens and inhibits Proteus swarming. नेपाली: Urine culture मा CLED ले Proteus को swarming रोक्छ।","explanationNe":"Urine culture मा CLED ले Proteus को swarming रोक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Which organism is a common cause of community-acquired urinary tract infection?","translation":"","options":["Escherichia coli","Vibrio cholerae","Neisseria meningitidis","Clostridium tetani"],"correctIndex":0,"explanation":"E. coli is the most frequent uncomplicated UTI pathogen. नेपाली: UTI को सामान्य कारण E. coli हो।","explanationNe":"UTI को सामान्य कारण E. coli हो।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Which specimen is preferred for diagnosing bacterial meningitis?","translation":"","options":["CSF","Sputum","Stool","Skin scraping"],"correctIndex":0,"explanation":"CSF is the key specimen for suspected bacterial meningitis. नेपाली: Meningitis शंका हुँदा CSF जाँचिन्छ।","explanationNe":"Meningitis शंका हुँदा CSF जाँचिन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Which organism requires enriched chocolate agar and increased CO2 for optimal growth?","translation":"","options":["Haemophilus influenzae","Proteus vulgaris","Clostridium perfringens","Bacillus cereus"],"correctIndex":0,"explanation":"H. influenzae requires X and V factors and grows on chocolate agar. नेपाली: H. influenzae लाई X र V factor चाहिन्छ।","explanationNe":"H. influenzae लाई X र V factor चाहिन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Which test is used to detect the enzyme that hydrolyses esculin in bile-esculin agar?","translation":"","options":["Esculin hydrolysis test","Indole test","Coagulase test","Oxidase test"],"correctIndex":0,"explanation":"Enterococci and group D streptococci commonly hydrolyse esculin in bile. नेपाली: Enterococcus ले bile-esculin positive दिन सक्छ।","explanationNe":"Enterococcus ले bile-esculin positive दिन सक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Which organism is typically urease-positive and strongly associated with struvite stones?","translation":"","options":["Proteus mirabilis","Streptococcus pneumoniae","Shigella flexneri","Neisseria gonorrhoeae"],"correctIndex":0,"explanation":"Proteus urease alkalinizes urine and promotes struvite formation. नेपाली: Proteus को urease ले urine alkaline बनाउँछ।","explanationNe":"Proteus को urease ले urine alkaline बनाउँछ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"Which culture medium is selective for Vibrio species?","translation":"","options":["TCBS agar","MacConkey agar","Blood agar","CLED agar"],"correctIndex":0,"explanation":"TCBS is selective for Vibrio; sucrose fermenters such as V. cholerae form yellow colonies. नेपाली: Vibrio isolation का लागि TCBS प्रयोग हुन्छ।","explanationNe":"Vibrio isolation का लागि TCBS प्रयोग हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Which organism produces black colonies on XLD agar due to hydrogen sulfide production?","translation":"","options":["Salmonella","Shigella","E. coli","Enterococcus"],"correctIndex":0,"explanation":"Many Salmonella produce H2S and black-centered colonies on XLD. नेपाली: Salmonella ले XLD मा कालो केन्द्र भएको colony दिन सक्छ।","explanationNe":"Salmonella ले XLD मा कालो केन्द्र भएको colony दिन सक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"Which test is used to detect beta-lactamase production in some bacteria?","translation":"","options":["Nitrocefin test","Catalase test","CAMP test","Bile solubility test"],"correctIndex":0,"explanation":"Nitrocefin is a chromogenic cephalosporin used to detect beta-lactamase. नेपाली: Nitrocefin beta-lactamase पत्ता लगाउन प्रयोग हुन्छ।","explanationNe":"Nitrocefin beta-lactamase पत्ता लगाउन प्रयोग हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"In Kirby–Bauer testing, the inoculum is standardized to approximately?","translation":"","options":["0.5 McFarland","5 McFarland","0.05 McFarland","10 McFarland"],"correctIndex":0,"explanation":"A 0.5 McFarland standard is used for routine disk diffusion inoculum. नेपाली: Kirby–Bauer मा 0.5 McFarland प्रयोग हुन्छ।","explanationNe":"Kirby–Bauer मा 0.5 McFarland प्रयोग हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"Which agar is standard for routine disk diffusion susceptibility testing?","translation":"","options":["Mueller–Hinton agar","Sabouraud agar","Lowenstein–Jensen medium","TCBS agar"],"correctIndex":0,"explanation":"Mueller–Hinton agar is the standard medium for many non-fastidious bacteria. नेपाली: Antibiotic disk diffusion मा Mueller–Hinton agar प्रयोग हुन्छ।","explanationNe":"Antibiotic disk diffusion मा Mueller–Hinton agar प्रयोग हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"What does MIC stand for?","translation":"","options":["Minimum inhibitory concentration","Maximum infection count","Minimum incubation cycle","Microbial identification code"],"correctIndex":0,"explanation":"MIC is the lowest antimicrobial concentration preventing visible growth under defined conditions. नेपाली: MIC ले वृद्धि रोक्ने सबैभन्दा कम औषधि मात्रा जनाउँछ।","explanationNe":"MIC ले वृद्धि रोक्ने सबैभन्दा कम औषधि मात्रा जनाउँछ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"A larger inhibition zone around an antibiotic disk generally indicates?","translation":"","options":["Greater susceptibility, interpreted using breakpoints","Guaranteed clinical cure","Higher bacterial virulence","Contamination"],"correctIndex":0,"explanation":"Zone diameter must be interpreted using organism-specific standards and breakpoints. नेपाली: Zone ठूलो हुनु sensitivity को संकेत हुन सक्छ, तर breakpoint अनुसार व्याख्या गर्नुपर्छ।","explanationNe":"Zone ठूलो हुनु sensitivity को संकेत हुन सक्छ, तर breakpoint अनुसार व्याख्या गर्नुपर्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"Which organism is intrinsically resistant to vancomycin among common Gram-negative bacteria because of its outer membrane?","translation":"","options":["Escherichia coli","Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis"],"correctIndex":0,"explanation":"The Gram-negative outer membrane prevents vancomycin access to its target. नेपाली: Gram-negative outer membrane ले vancomycin प्रवेश रोक्छ।","explanationNe":"Gram-negative outer membrane ले vancomycin प्रवेश रोक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-practice-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"Which infection-control practice is essential when handling suspected meningococcal specimens?","translation":"","options":["Appropriate biosafety precautions and prompt processing","Open-bench aerosol generation","Mouth pipetting","Leaving specimens uncapped"],"correctIndex":0,"explanation":"Use appropriate containment, PPE and laboratory SOPs for potentially infectious material. नेपाली: PPE र biosafety SOP अनिवार्य पालना गर्नुपर्छ।","explanationNe":"PPE र biosafety SOP अनिवार्य पालना गर्नुपर्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
