('bmlt-bacteriology-ast1-practice-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"Which result best supports a pure bacterial culture?","translation":"","options":["One consistent colony morphology after isolation streaking","Many unrelated colony types","Mixed Gram reaction from multiple colony types","Growth only in an expired medium"],"correctIndex":0,"explanation":"A pure culture should yield a consistent organism morphology and identification profile. नेपाली: शुद्ध culture मा एउटै प्रकारको colony देखिनुपर्छ।","explanationNe":"शुद्ध culture मा एउटै प्रकारको colony देखिनुपर्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"A stool isolate forms red colonies with black centers on XLD agar. Which organism is most likely?","translation":"","options":["Salmonella species","Shigella species","E. coli","Enterococcus species"],"correctIndex":0,"explanation":"Salmonella commonly produces red colonies with black centers from H2S. नेपाली: XLD मा कालो केन्द्र Salmonella को संकेत हुन सक्छ।","explanationNe":"XLD मा कालो केन्द्र Salmonella को संकेत हुन सक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
