('bmlt-bacteriology-ast1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A Gram-positive coccus is catalase-positive and coagulase-positive. Identification is most consistent with?","translation":"","options":["Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae"],"correctIndex":0,"explanation":"S. aureus is classically catalase- and coagulase-positive. नेपाली: दुवै positive भए S. aureus सम्भावित हुन्छ।","explanationNe":"दुवै positive भए S. aureus सम्भावित हुन्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
