('bmlt-bacteriology-ast1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A non-lactose-fermenting isolate from stool is oxidase-positive and grows on TCBS as yellow colonies. Which organism is likely?","translation":"","options":["Vibrio cholerae","Shigella sonnei","Salmonella Typhi","Proteus mirabilis"],"correctIndex":0,"explanation":"V. cholerae ferments sucrose and forms yellow colonies on TCBS. नेपाली: TCBS मा पहेँलो colony Vibrio cholerae हुन सक्छ।","explanationNe":"TCBS मा पहेँलो colony Vibrio cholerae हुन सक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
