('bmlt-bacteriology-ast1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A disk diffusion test was inoculated with a very heavy bacterial suspension. What is the likely effect?","translation":"","options":["Smaller inhibition zones and possible false resistance","Larger zones and false susceptibility","No effect on results","Automatic sterile plate"],"correctIndex":0,"explanation":"An overly dense inoculum can reduce zone sizes and distort interpretation. नेपाली: बाक्लो inoculum ले zone सानो देखाएर गलत resistance दिन सक्छ।","explanationNe":"बाक्लो inoculum ले zone सानो देखाएर गलत resistance दिन सक्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
('bmlt-bacteriology-ast1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"The measured inhibition zone is 18 mm. Can susceptibility be concluded without knowing the organism and antibiotic?","translation":"","options":["No, use organism-drug-specific breakpoints","Yes, 18 mm is always susceptible","Yes, any zone means susceptible","No, all zones mean resistant"],"correctIndex":0,"explanation":"Zone diameters require current standardized breakpoints for the organism and drug. नेपाली: Organism र antibiotic अनुसार breakpoint हेर्नुपर्छ।","explanationNe":"Organism र antibiotic अनुसार breakpoint हेर्नुपर्छ।","topic":"Clinical Bacteriology & Antimicrobial Susceptibility Testing"}'::jsonb,true),
